const sd = $getWorkflowStaticData('global');
const last = sd.lastUpdateId || 0;
return [{ json: { offset: last ? last + 1 : 0 } }];

// Emit one item per actionable update.
// Legacy kinds (unchanged): 'image', 'text', 'topics'.
// Instant-Post kinds: 'cbedit'/'cbpost' (button taps) and 'ipdraft'/'ipawait'/
// 'ipedit'/'iptime' (Abhishek's own material / edit / time replies). Which IP
// kind a plain message is depends on the chat's CURRENT draft status. A Code
// node can't query the linkedin_drafts Data Table inline, so status is read
// from a static-data mirror (sd.ipDrafts) that every transition write-through-
// mirrors to the table for durability/inspection.
const res = $input.first().json || {};
const updates = Array.isArray(res.result) ? res.result : [];
const sd = $getWorkflowStaticData('global');
if (!sd.ipDrafts) sd.ipDrafts = {};
let maxId = sd.lastUpdateId || 0;
const MK = /^\[{1,2}go:(\d{4}-\d{2}-\d{2})\]{1,2}\r?\n?/;
const out = [];
for (const u of updates) {
  if (typeof u.update_id === 'number' && u.update_id > maxId) maxId = u.update_id;

  // A) button tap
  const cq = u.callback_query;
  if (cq) {
    const m = cq.message || {};
    const data = cq.data || '';
    const chatId = m.chat && m.chat.id;
    if (data === 'ip_edit') { out.push({ json: { kind: 'cbedit', chatId, messageId: m.message_id, callbackQueryId: cq.id } }); continue; }
    if (data === 'ip_post') { out.push({ json: { kind: 'cbpost', chatId, messageId: m.message_id, callbackQueryId: cq.id } }); continue; }
    // legacy v2-approve button -> text-only publish
    let t = m.text || m.caption || '';
    const mk = t.match(MK); if (mk) t = t.slice(mk[0].length);
    out.push({ json: { kind: 'text', postText: t, fileId: '', callbackQueryId: cq.id, chatId, messageId: m.message_id } });
    continue;
  }

  const msg = u.message;
  if (!msg) continue;
  const chatId = msg.chat && msg.chat.id;

  // B) photo reply -> schedule for the post's own day (legacy)
  if (msg.reply_to_message) {
    let fileId = '';
    if (Array.isArray(msg.photo) && msg.photo.length) fileId = msg.photo[msg.photo.length - 1].file_id;
    else if (msg.document && /^image\//.test(msg.document.mime_type || '')) fileId = msg.document.file_id;
    if (!fileId) continue;
    let rtext = msg.reply_to_message.text || msg.reply_to_message.caption || '';
    const mk = rtext.match(MK);
    let targetDate = '';
    if (mk) { targetDate = mk[1]; rtext = rtext.slice(mk[0].length); }
    const postText = rtext;
    if (!postText.trim() || postText.startsWith('📅') || postText.startsWith('↩')) continue;
    out.push({ json: { kind: 'image', postText, fileId, targetDate, chatId, messageId: msg.message_id } });
    continue;
  }

  const status = (sd.ipDrafts[chatId] && sd.ipDrafts[chatId].status) || 'idle';

  // C) legacy "topics: ..." steering (only when idle, so it can't hijack an edit/time turn)
  if (status === 'idle' && !msg.photo && typeof msg.text === 'string') {
    const tm = msg.text.match(/^\s*topics\s*:\s*(.+)$/i);
    if (tm) { out.push({ json: { kind: 'topics', topics: tm[1].trim(), chatId } }); continue; }
  }

  // D) Instant-Post material / follow-ups
  let photoFileId = '';
  if (Array.isArray(msg.photo) && msg.photo.length) photoFileId = msg.photo[msg.photo.length - 1].file_id;
  else if (msg.document && /^image\//.test(msg.document.mime_type || '')) photoFileId = msg.document.file_id;
  let voiceFileId = '';
  if (msg.voice && msg.voice.file_id) voiceFileId = msg.voice.file_id;
  else if (msg.audio && msg.audio.file_id) voiceFileId = msg.audio.file_id;
  const text = msg.caption || msg.text || '';
  const hasPhoto = !!photoFileId, hasVoice = !!voiceFileId;

  let kind = '';
  if (status === 'awaiting_time') kind = 'iptime';
  else if (status === 'awaiting_edit') kind = 'ipedit';
  else if (status === 'awaiting_photo') kind = hasPhoto ? 'ipdraft' : ((hasVoice || text.trim()) ? 'ipawait' : '');
  else {
    if (hasVoice && hasPhoto) kind = 'ipdraft';
    else if (hasPhoto && text.trim()) kind = 'ipdraft';
    else if (hasVoice) kind = 'ipawait';
  }
  if (!kind) continue;
  out.push({ json: { kind, chatId, messageId: msg.message_id, text, photoFileId, voiceFileId, callbackQueryId: '' } });
}
sd.lastUpdateId = maxId;
return out;

// Queue the photo-reply for its post's OWN day at 06:00 Africa/Nairobi (EAT, fixed UTC+3).
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.scheduledPosts)) sd.scheduledPosts = [];
const queue = sd.scheduledPosts;
const inp = $input.first().json;
const EAT = 3 * 60 * 60 * 1000;

function slotFromDate(dstr) {                 // 'YYYY-MM-DD' EAT -> 06:00 EAT as UTC ms
  const [y, m, d] = dstr.split('-').map(Number);
  return Date.UTC(y, m - 1, d, 6, 0, 0, 0) - EAT;
}
function nextWeekday6(baseMs) {               // fallback if no marker date present
  const w = new Date(baseMs + EAT);
  const y = w.getUTCFullYear(), mo = w.getUTCMonth(), d0 = w.getUTCDate();
  for (let i = 0; i < 14; i++) {
    const wallMs = Date.UTC(y, mo, d0 + i, 6, 0, 0, 0);
    const utcMs = wallMs - EAT;
    const dow = new Date(wallMs).getUTCDay();
    if (utcMs > baseMs && dow >= 1 && dow <= 5) return utcMs;
  }
  return baseMs;
}

const slotMs = /^\d{4}-\d{2}-\d{2}$/.test(inp.targetDate || '')
  ? slotFromDate(inp.targetDate)
  : nextWeekday6(Date.now());

const goLiveISO = new Date(slotMs).toISOString();
const id = `${Date.now()}-${Math.floor(Math.random() * 1e6)}`;
queue.push({ id, postText: inp.postText, fileId: inp.fileId, goLiveISO, posted: false });

const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const mons = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const wall = new Date(slotMs + EAT);
const label = `${days[wall.getUTCDay()]} ${String(wall.getUTCDate()).padStart(2, '0')} ${mons[wall.getUTCMonth()]}`;
return [{ json: { chatId: inp.chatId, goLiveISO, label } }];

// Every run: for each unposted item -> publish today's (>=06:00), cancel past days, wait on future.
const sd = $getWorkflowStaticData('global');
const queue = Array.isArray(sd.scheduledPosts) ? sd.scheduledPosts : [];
const EAT = 3 * 60 * 60 * 1000;
const now = Date.now();
const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const mons = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dayNum = (ms) => { const w = new Date(ms + EAT); return w.getUTCFullYear() * 10000 + (w.getUTCMonth() + 1) * 100 + w.getUTCDate(); };
const today = dayNum(now);
const out = [];
for (const p of queue) {
  if (p.posted || p.cancelled) continue;
  const t = Date.parse(p.goLiveISO);
  if (isNaN(t)) continue;
  const itemDay = dayNum(t);
  const w = new Date(t + EAT);
  const label = `${days[w.getUTCDay()]} ${String(w.getUTCDate()).padStart(2, '0')} ${mons[w.getUTCMonth()]}`;
  if (itemDay < today) {
    p.cancelled = true;                                   // missed its day -> drop, never publish
    out.push({ json: { kind: 'cancel', id: p.id, label } });
  } else if (itemDay === today && now >= t) {
    out.push({ json: { kind: 'publish', id: p.id, postText: p.postText, fileId: p.fileId, label } });
  } // else: future -> wait
}
return out;

// Mark the just-published item posted:true and persist to shared static data.
const sd = $getWorkflowStaticData('global');
const queue = Array.isArray(sd.scheduledPosts) ? sd.scheduledPosts : [];
const id = $('Scan Queue').item.json.id;
for (const p of queue) { if (p.id === id) { p.posted = true; break; } }
return $input.all();

// Base64-encode the downloaded voice note for Gemini inlineData. IF passes the
// item through unchanged, so original fields come from 'Route: has voice?'.
const src = $('Route: has voice?').item.json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: Object.assign({}, src, { audioB64: buf.toString('base64') }) }];

// Combine caption + Gemini transcript into userText.
const src = $('Route: has voice?').item.json;
let transcript = '';
try { transcript = $json.candidates[0].content.parts[0].text || ''; } catch (e) {}
const userText = [src.text, transcript].filter(s => s && s.trim()).join('\n').trim();
return [{ json: Object.assign({}, src, { userText }) }];

// No voice: userText is just the text/caption. IF passed the item through.
const src = $json;
return [{ json: Object.assign({}, src, { userText: (src.text || '').trim() }) }];

// Merge fresh notes with any stored notes (voice-first -> awaiting_photo -> photo).
const s = $json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[s.chatId] || {};
const notes = ((prior.status === 'awaiting_photo' && prior.notes) ? prior.notes + '\n' : '') + (s.userText || '');
const photoFileId = s.photoFileId || prior.photoFileId || '';
sd.ipDrafts[s.chatId] = Object.assign({}, prior, { status: 'drafting', notes, photoFileId, chatId: s.chatId });
return [{ json: { chatId: s.chatId, notes, photoFileId } }];

// Store the generated draft; move to awaiting_action.
let draftText = '';
try { draftText = $json.candidates[0].content.parts[0].text || ''; } catch (e) {}
draftText = draftText.trim();
const p = $('Prep Draft').item.json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[p.chatId] || {};
sd.ipDrafts[p.chatId] = Object.assign({}, prior, { status: 'awaiting_action', draftText, photoFileId: p.photoFileId, notes: p.notes, chatId: p.chatId });
return [{ json: { chatId: p.chatId, status: 'awaiting_action', notes: p.notes, draftText, photoFileId: p.photoFileId } }];

// Voice-only material (or more notes while awaiting a photo): stash notes, ask for the photo.
const s = $json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[s.chatId] || {};
const notes = ((prior.status === 'awaiting_photo' && prior.notes) ? prior.notes + '\n' : '') + (s.userText || '');
sd.ipDrafts[s.chatId] = Object.assign({}, prior, { status: 'awaiting_photo', notes, chatId: s.chatId });
return [{ json: { chatId: s.chatId, status: 'awaiting_photo', notes, draftText: prior.draftText || '', photoFileId: prior.photoFileId || '' } }];

// Prepare a redraft from the prior draft + his change instructions.
const s = $json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[s.chatId] || {};
return [{ json: { chatId: s.chatId, prevDraft: prior.draftText || '', instructions: s.userText || '', notes: prior.notes || '', photoFileId: prior.photoFileId || '' } }];

// Store the revised draft; back to awaiting_action.
let draftText = '';
try { draftText = $json.candidates[0].content.parts[0].text || ''; } catch (e) {}
draftText = draftText.trim();
const p = $('Prep Redraft').item.json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[p.chatId] || {};
sd.ipDrafts[p.chatId] = Object.assign({}, prior, { status: 'awaiting_action', draftText, photoFileId: p.photoFileId, notes: p.notes, chatId: p.chatId });
return [{ json: { chatId: p.chatId, status: 'awaiting_action', notes: p.notes, draftText, photoFileId: p.photoFileId } }];

// Give Gemini the current time so it can resolve 'now' / 'tomorrow 9am' etc.
const s = $json;
return [{ json: { chatId: s.chatId, phrase: s.userText || '', nowIso: new Date().toISOString() } }];

// Parse Gemini's JSON verdict -> post now, or push to the SAME scheduledPosts queue.
let txt = '';
try { txt = $json.candidates[0].content.parts[0].text || ''; } catch (e) {}
txt = txt.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = { mode: 'schedule' };
try { parsed = JSON.parse(txt); } catch (e) {}
const p = $('Prep Time').item.json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[p.chatId] || {};
const draftText = prior.draftText || '', photoFileId = prior.photoFileId || '', notes = prior.notes || '';
if (parsed.mode === 'now') {
  sd.ipDrafts[p.chatId] = Object.assign({}, prior, { status: 'posted', chatId: p.chatId });
  return [{ json: { chatId: p.chatId, mode: 'now', status: 'posted', notes, draftText, photoFileId, label: 'now' } }];
}
let t = Date.parse(parsed.iso);
if (isNaN(t)) { t = Date.now() + 3600000; }               // unparseable -> +1h fallback
const goLiveISO = new Date(t).toISOString();
if (!Array.isArray(sd.scheduledPosts)) sd.scheduledPosts = [];
const id = `${Date.now()}-${Math.floor(Math.random() * 1e6)}`;
sd.scheduledPosts.push({ id, postText: draftText, fileId: photoFileId, goLiveISO, posted: false });
sd.ipDrafts[p.chatId] = Object.assign({}, prior, { status: 'scheduled', chatId: p.chatId });
const EAT = 3 * 60 * 60 * 1000;
const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const mons = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const w = new Date(t + EAT);
const label = `${days[w.getUTCDay()]} ${String(w.getUTCDate()).padStart(2,'0')} ${mons[w.getUTCMonth()]} ${String(w.getUTCHours()).padStart(2,'0')}:${String(w.getUTCMinutes()).padStart(2,'0')}`;
return [{ json: { chatId: p.chatId, mode: 'schedule', status: 'scheduled', notes, draftText, photoFileId, goLiveISO, label } }];

// Edit / Post button -> set the follow-up state and the prompt to send.
const s = $json;
const sd = $getWorkflowStaticData('global'); if (!sd.ipDrafts) sd.ipDrafts = {};
const prior = sd.ipDrafts[s.chatId] || {};
const isEdit = s.kind === 'cbedit';
const status = isEdit ? 'awaiting_edit' : 'awaiting_time';
const prompt = isEdit
  ? '✏️ Send your changes (type or voice note).'
  : "🕒 When should it go live? (e.g. 'now', 'tomorrow 9am', 'Thu 2pm').";
sd.ipDrafts[s.chatId] = Object.assign({}, prior, { status, chatId: s.chatId });
return [{ json: { chatId: s.chatId, status, notes: prior.notes || '', draftText: prior.draftText || '', photoFileId: prior.photoFileId || '', prompt } }];
